<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityUserVO;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityRelyingPartyVO;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityTrustedClientVO;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityRolesVO;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityVersionVO;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Usecase\Retrieve\ClientIdentityRetrieveResult;
use PHPUnit\Framework\TestCase;

final class ClientIdentityRetrieveResultUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new ClientIdentityRetrieveResult();
        $userOneValue = new UserRef('one');
        $userOtherValue = new UserRef('other');
        $copy = $value->user($userOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new UserRef('one'), $value->getUser());
        $this->assertNotEquals(new UserRef('other'), $value->getUser());
        $this->assertEquals(new UserRef('one'), $value->getUserOrDefault(ClientIdentityUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('other'), $value->getUserOrDefault(ClientIdentityUserVO::from($userOtherValue))->value());
        $value->unsetUser();
        $this->assertEquals(new UserRef('other'), $value->getUserOrDefault(ClientIdentityUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('one'), $value->getUserOrDefault(ClientIdentityUserVO::from($userOtherValue))->value());
        $relyingPartyOneValue = new RelyingPartyRef('one');
        $relyingPartyOtherValue = new RelyingPartyRef('other');
        $copy = $value->relyingParty($relyingPartyOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new RelyingPartyRef('one'), $value->getRelyingParty());
        $this->assertNotEquals(new RelyingPartyRef('other'), $value->getRelyingParty());
        $this->assertEquals(new RelyingPartyRef('one'), $value->getRelyingPartyOrDefault(ClientIdentityRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $this->assertNotEquals(new RelyingPartyRef('other'), $value->getRelyingPartyOrDefault(ClientIdentityRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $value->unsetRelyingParty();
        $this->assertEquals(new RelyingPartyRef('other'), $value->getRelyingPartyOrDefault(ClientIdentityRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $this->assertNotEquals(new RelyingPartyRef('one'), $value->getRelyingPartyOrDefault(ClientIdentityRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $trustedClientOneValue = new TrustedClientRef('one');
        $trustedClientOtherValue = new TrustedClientRef('other');
        $copy = $value->trustedClient($trustedClientOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClient());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClient());
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClientOrDefault(ClientIdentityTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClientOrDefault(ClientIdentityTrustedClientVO::from($trustedClientOtherValue))->value());
        $value->unsetTrustedClient();
        $this->assertEquals(new TrustedClientRef('other'), $value->getTrustedClientOrDefault(ClientIdentityTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('one'), $value->getTrustedClientOrDefault(ClientIdentityTrustedClientVO::from($trustedClientOtherValue))->value());
        $rolesOneValue = 'one';
        $rolesOtherValue = 'other';
        $copy = $value->roles($rolesOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getRoles());
        $this->assertNotEquals('other', $value->getRoles());
        $this->assertEquals('one', $value->getRolesOrDefault(ClientIdentityRolesVO::from($rolesOtherValue))->value());
        $this->assertNotEquals('other', $value->getRolesOrDefault(ClientIdentityRolesVO::from($rolesOtherValue))->value());
        $value->unsetRoles();
        $this->assertEquals('other', $value->getRolesOrDefault(ClientIdentityRolesVO::from($rolesOtherValue))->value());
        $this->assertNotEquals('one', $value->getRolesOrDefault(ClientIdentityRolesVO::from($rolesOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrDefault(ClientIdentityVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrDefault(ClientIdentityVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrDefault(ClientIdentityVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrDefault(ClientIdentityVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
